        children: "interface JobDescription {\n  title: string;\n  requiredSkills: string[];\n  preferredSkills: string[];\n  responsibilities: string[];\n  qualifications: string[];\n}\n\ninterface ResumeAnalysis {\n  matchScore: number;\n  matchedKeywords: string[];\n  missingKeywords: string[];\n  suggestions: string[];\n}\n\nclass ATSOptimizer {\n  analyzeResumeForJD(\n    resumeText: string,\n    jobDescription: JobDescription\n  ): ResumeAnalysis {\n    const normalize = (text: string): string =>\n      text.toLowerCase().replace(/[^a-z0-9\\s+#.-]/g, '');\n\n    const normalizedResume = normalize(resumeText);\n    const allJDKeywords = [\n      ...jobDescription.requiredSkills,\n      ...jobDescription.preferredSkills,\n      ...jobDescription.responsibilities,\n      ...jobDescription.qualifications,\n    ].map((k) => normalize(k));\n\n    const allUniqueWords = new Set(\n      normalizedResume.split(/\\s+/).filter(Boolean)\n    );\n\n    const matched: string[] = [];\n    const missing: string[] = [];\n\n    for (const keyword of allJDKeywords) {\n      const words = keyword.split(/\\s+/);\n      const isPresent = words.every((w) => allUniqueWords.has(w));\n\n      if (isPresent) {\n        if (!matched.includes(keyword)) matched.push(keyword);\n      } else {\n        if (!missing.includes(keyword)) missing.push(keyword);\n      }\n    }\n\n    const matchScore = allJDKeywords.length > 0\n      ? Math.round((matched.length / allJDKeywords.length) * 100)\n      : 0;\n\n    const suggestions = this.generateSuggestions(missing, jobDescription);\n\n    return { matchScore, matchedKeywords: matched, missingKeywords: missing, suggestions };\n  }\n\n  private generateSuggestions(\n    missingKeywords: string[],\n    jd: JobDescription\n  ): string[] {\n    const suggestions: string[] = [];\n\n    const requiredMissing = missingKeywords.filter((k) =>\n      jd.requiredSkills.some((s) => s.toLowerCase().includes(k))\n    );\n    if (requiredMissing.length > 0) {\n      suggestions.push(\n        `Add these required skills to your resume: ${requiredMissing.join(', ')}`\n      );\n    }\n\n    const toolPatterns = [\n      'aws', 'azure', 'gcp', 'docker', 'kubernetes',\n      'react', 'angular', 'node', 'python', 'java',\n      'sql', 'mongodb', 'redis',\n    ];\n    for (const missing of missingKeywords) {\n      if (toolPatterns.some((t) => missing.includes(t))) {\n        suggestions.push(\n          `Consider adding \"${missing}\" to your Technical Skills section if you have experience`\n        );\n      }\n    }\n\n    return suggestions;\n  }\n}\n\nconst optimizer = new ATSOptimizer();\n\nconst sampleJD: JobDescription = {\n  title: 'Senior Full-Stack Developer',\n  requiredSkills: [\n    'TypeScript', 'React', 'Node.js', 'PostgreSQL',\n    'AWS', 'Docker', 'REST APIs', 'Git',\n  ],\n  preferredSkills: [\n    'GraphQL', 'Kubernetes', 'Redis', 'Microservices',\n    'CI/CD', 'Terraform', 'Next.js',\n  ],\n  responsibilities: [\n    'Design and implement scalable microservices',\n    'Mentor junior developers',\n    'Code review and quality assurance',\n    'Performance optimization',\n  ],\n  qualifications: [\n    'B.Tech in Computer Science or equivalent',\n    '4+ years of software development experience',\n  ],\n};\n\nconst sampleResume = `\nExperienced Software Engineer with 5 years in full-stack development.\nProficient in TypeScript, React, Node.js, and PostgreSQL.\nBuilt REST APIs and deployed applications on AWS using Docker.\nExperienced with Git for version control.\n`;\n\nconst analysis = optimizer.analyzeResumeForJD(sampleResume, sampleJD);\nconsole.log('ATS Match Score:', analysis.matchScore + '%');\nconsole.log('Matched Keywords:', analysis.matchedKeywords);\nconsole.log('Missing Keywords:', analysis.missingKeywords);\nconsole.log('Suggestions:', analysis.suggestions);\n"
